-- Backfill of the user-facing PRs merged since 06.11. (both repos) into the changelog table, written for visitors, DE + EN.
-- Internal PRs (CI, docs, templates, refactors, audits, admin-only work) are left out, as are the six changes 0020 already
-- seeded (blog editor, clean links, NwebOS desktop, new home page, faster site, one navigation) and the entries 0023 imports.
-- day = the merge day in Berlin time; source = '<repo>#<n>' (the unique index from 0022 makes a re-run add nothing).
-- Applied by CF Deployer after 0023:  npx wrangler d1 execute nwebnotfound-guestbook --remote --file migrations/0024_changelog_backfill.sql

INSERT OR IGNORE INTO changelog (day, area, title_de, title_en, text_de, text_en, status, sort, version, updated_at, source, edited) VALUES ('2026-11-06', 'website', 'Dein privates Profil', 'Your private profile', 'Die Profilseite siehst nur du: mit deinem Namen, deinen Zahlen und deinen Einstellungen.', 'Only you can see your profile page, with your name, your numbers and your settings.', 'live', 1, 1, 1762560000000, 'NwebNotFound/NwebNotFoundDOTDev#99', 0);
INSERT OR IGNORE INTO changelog (day, area, title_de, title_en, text_de, text_en, status, sort, version, updated_at, source, edited) VALUES ('2026-11-06', 'server', 'Aufgeräumte VIP-Seite', 'Tidier VIP page', 'Weltnamen, Rang-Karten und Inventar-Felder auf mc.nwebnotfound.dev sind sauberer dargestellt.', 'World names, rank cards and inventory slots on mc.nwebnotfound.dev are laid out more cleanly.', 'live', 2, 1, 1762560000000, 'NwebNotFound/NwebNotFoundDOTDev#97', 0);
INSERT OR IGNORE INTO changelog (day, area, title_de, title_en, text_de, text_en, status, sort, version, updated_at, source, edited) VALUES ('2026-11-07', 'website', 'Pixelminen und Fünf', 'Pixel Mines and Five', 'Zwei kleine Spiele direkt im NwebOS: Minensuche und ein Wortratespiel mit fünf Buchstaben.', 'Two small games right in NwebOS: minesweeper and a five-letter word guessing game.', 'live', 1, 1, 1762560000000, 'NwebNotFound/NwebNotFoundDOTDev#114', 0);
INSERT OR IGNORE INTO changelog (day, area, title_de, title_en, text_de, text_en, status, sort, version, updated_at, source, edited) VALUES ('2026-11-07', 'website', 'Schöneres NwebOS auf dem Handy', 'Nicer NwebOS on your phone', 'Einheitliche Buttons, Pixel-Icons, ein überarbeiteter Musik-Player und bessere Nachtfarben.', 'Consistent buttons, pixel icons, a reworked music player and better night colours.', 'live', 2, 1, 1762560000000, 'NwebNotFound/NwebNotFoundDOTDev#120', 0);
INSERT OR IGNORE INTO changelog (day, area, title_de, title_en, text_de, text_en, status, sort, version, updated_at, source, edited) VALUES ('2026-11-08', 'website', 'Fünf prüft deine Wörter', 'Five checks your words', 'Nur echte deutsche oder englische Wörter zählen, Ä, Ö und Ü gibt es als Tasten, und ein ungültiges Wort kostet keine Zeile.', 'Only real German or English words count, Ä, Ö and Ü have their own keys, and an invalid word doesn''t use up a row.', 'live', 1, 1, 1762560000000, 'NwebNotFound/NwebNotFoundDOTDev#124', 0);
INSERT OR IGNORE INTO changelog (day, area, title_de, title_en, text_de, text_en, status, sort, version, updated_at, source, edited) VALUES ('2026-11-08', 'website', 'Handy-Suche und Schnellmenü', 'Phone search and quick menu', 'Die Suche zeigt Treffer mit Symbolen, das Schnellmenü bündelt Konto, Tag/Nacht und Ton, und die Neuigkeiten lassen sich als RSS abonnieren.', 'Search shows results with icons, the quick menu bundles account, day/night and sound, and the news can be subscribed to as RSS.', 'live', 2, 1, 1762560000000, 'NwebNotFound/NwebNotFoundDOTDev#123', 0);
INSERT OR IGNORE INTO changelog (day, area, title_de, title_en, text_de, text_en, status, sort, version, updated_at, source, edited) VALUES ('2026-11-08', 'website', 'Mein Profil neu gebaut', 'My profile, rebuilt', 'Das Profil hat Tabs für Übersicht, Spiele, Abzeichen und Einstellungen; Spielstände und Einstellungen wandern mit deinem Konto.', 'The profile has tabs for overview, games, badges and settings; your game stats and settings follow your account.', 'live', 3, 1, 1762560000000, 'NwebNotFound/NwebNotFoundDOTDev#127', 0);
INSERT OR IGNORE INTO changelog (day, area, title_de, title_en, text_de, text_en, status, sort, version, updated_at, source, edited) VALUES ('2026-11-08', 'website', 'Jede Seite ist ein Fenster', 'Every page is a window', 'Die alte Ansicht der Website ist weg: Alles öffnet als NwebOS-Fenster, und Texte haben ein eigenes Lesefenster.', 'The old view of the site is gone: everything opens as an NwebOS window, and texts have their own reading window.', 'live', 4, 1, 1762560000000, 'NwebNotFound/NwebNotFoundDOTDev#125', 0);
INSERT OR IGNORE INTO changelog (day, area, title_de, title_en, text_de, text_en, status, sort, version, updated_at, source, edited) VALUES ('2026-11-08', 'server', 'VIP-Welten zeigen ihren echten Status', 'VIP worlds show their real status', 'Eine beendete Welt steht wieder auf „gestoppt“ und lässt sich auf /vip und im Spiel neu starten.', 'A world that ended is shown as stopped again and can be restarted on /vip and in game.', 'live', 5, 1, 1762560000000, 'NwebNotFound/mc-stack#183', 0);
